    </style>
  </head>
  <body>
    <a class="skip-link" href="#main-content">Skip to main content</a>

    <main id="main-content">
      <section class="card" aria-labelledby="page-title">
        <p class="eyebrow">Preferences</p>
        <h1 id="page-title">Choose your notification style</h1>
        <p class="intro">
          Select the channel that works best for you. You can update this
          preference later.
        </p>

        <form id="notification-form">
          <p class="required-note">
            Fields marked with <span class="required-marker" aria-hidden="true">*</span>
            are required.
          </p>

          <div class="form-field">
            <fieldset aria-describedby="notification-help">
              <legend>
                How do you prefer to receive notifications?
                <span class="required-marker" aria-hidden="true">*</span>
              </legend>
              <p class="field-help" id="notification-help">Choose one option.</p>

              <div class="radio-options">
                <label class="radio-option" for="notification-email">
                  <input
                    id="notification-email"
                    type="radio"
                    name="notificationPreference"
                    value="email"
                    required
                  >
                  <span>Email</span>
                </label>

                <label class="radio-option" for="notification-sms">
                  <input
                    id="notification-sms"
                    type="radio"
                    name="notificationPreference"
                    value="sms"
                    required
                  >
                  <span>SMS</span>
                </label>

                <label class="radio-option" for="notification-push">
                  <input
                    id="notification-push"
                    type="radio"
                    name="notificationPreference"
                    value="push"
                    required
                  >
                  <span>Push Notifications</span>
                </label>
              </div>
            </fieldset>
          </div>

          <button type="submit">Save preference</button>
          <p class="status" id="form-status" aria-live="polite"></p>
        </form>
      </section>
    </main>

    <script>
      const form = document.querySelector("#notification-form");
      const statusMessage = document.querySelector("#form-status");

      form.addEventListener("submit", (event) => {
        event.preventDefault();

        if (!form.reportValidity()) {
          statusMessage.textContent = "";
          return;
        }

        const selectedPreference = new FormData(form).get("notificationPreference");
        const selectedLabel = form.querySelector(
          `input[name="notificationPreference"][value="${selectedPreference}"] + span`
        ).textContent;

        statusMessage.textContent = `Preference saved: ${selectedLabel}.`;
      });
    </script>
  </body>
</html>
