        font: inherit;
        font-weight: 800;
        cursor: pointer;
        box-shadow: 0 12px 24px rgba(37, 99, 235, 0.24);
      }

      button:hover {
        background: var(--accent-strong);
      }

      button:focus-visible {
        outline: 3px solid var(--text);
        outline-offset: 3px;
      }

